import React, { useMemo } from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring } from '../remotionShim';


export type GearSyncProps = Record<string, any>;

const createGearPath = (N: number, Rp: number, H: number, Rhole: number) => {
  const step = (Math.PI * 2) / N;
  const Rout = Rp + H / 2;
  const Rin = Rp - H / 2 - 5; // -5px adds clearance to the root
  let d = "";

  for (let i = 0; i < N; i++) {
    // Tooth profile angles
    const a1 = i * step - step * 0.08; // Tip left
    const a2 = i * step + step * 0.08; // Tip right
    const a3 = i * step + step * 0.28; // Root right
    const a4 = i * step + step * 0.72; // Root left (for next tooth gap)

    const p1x = Rout * Math.cos(a1);
    const p1y = Rout * Math.sin(a1);
    const p2x = Rout * Math.cos(a2);
    const p2y = Rout * Math.sin(a2);
    const p3x = Rin * Math.cos(a3);
    const p3y = Rin * Math.sin(a3);
    const p4x = Rin * Math.cos(a4);
    const p4y = Rin * Math.sin(a4);

    if (i === 0) {
      d += `M ${p1x} ${p1y} `;
    } else {
      d += `L ${p1x} ${p1y} `;
    }
    d += `L ${p2x} ${p2y} L ${p3x} ${p3y} L ${p4x} ${p4y} `;
  }
  d += "Z";

  // Center hole drawn counter-clockwise for evenodd fill rule
  if (Rhole > 0) {
    d += ` M ${Rhole} 0 A ${Rhole} ${Rhole} 0 1 0 ${-Rhole} 0 A ${Rhole} ${Rhole} 0 1 0 ${Rhole} 0 Z`;
  }
  
  return d;
};

const Gear: React.FC<{
  N: number;
  Rp: number;
  H: number;
  Rhole: number;
  color: string;
  rotation: number;
  x: number;
  y: number;
  styleType: "Solid" | "Outline";
  scale: number;
}> = ({ N, Rp, H, Rhole, color, rotation, x, y, styleType, scale }) => {
  const path = useMemo(() => createGearPath(N, Rp, H, Rhole), [N, Rp, H, Rhole]);

  return (
    <g transform={`translate(${x}, ${y}) scale(${scale}) rotate(${rotation})`}>
      <path
        d={path}
        fill={styleType === "Solid" ? color : "none"}
        stroke={styleType === "Outline" ? color : "none"}
        strokeWidth={styleType === "Outline" ? 6 : 0}
        fillRule="evenodd"
        style={{ transition: "none" }}
      />
    </g>
  );
};

const GearSync: React.FC<GearSyncProps> = ({
  backgroundColor = "#0F172A",
  transparentBackground = false,
  durationInSeconds = 10,
  primaryGearColor = "#4F46E5",
  secondaryGearColor = "#EC4899",
  axleColor = "#94A3B8",
  rotationSpeed = 1.0,
  gearStyle = "Solid",
  zoomLevel = 1.0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Spring physics for entrance scale
  const entranceScale = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 100 },
    durationInFrames: Math.round(fps * 1.5),
  });

  // Structural Constants
  const N1 = 18; // Primary Gear Teeth
  const N2 = 12; // Secondary Gear Teeth
  const M = 40;  // Module (Size scalar per tooth)
  
  // Pitch Radii (Distance from center to the middle of the teeth)
  const Rp1 = (M * N1) / 2; // 360
  const Rp2 = (M * N2) / 2; // 240
  
  // Total distance between exact centers required for perfect meshing
  const D = Rp1 + Rp2; // 600

  // Layout Centering
  const centerX = width / 2;
  const centerY = height / 2;
  const x1 = centerX - D / 2;
  const x2 = centerX + D / 2;

  // Motion Math
  const totalFrames = Math.max(1, Math.round(fps * durationInSeconds));
  const totalRotations = durationInSeconds * rotationSpeed;
  
  // Primary gear rotates continuously
  const angle1 = interpolate(
    frame,
    [0, totalFrames],
    [0, 360 * totalRotations]
  );

  // Secondary gear rotates in reverse at a proportionally faster speed.
  // The offset guarantees the tooth of gear 1 matches the gap of gear 2.
  const offset2 = 180 / N2;
  const angle2 = -angle1 * (N1 / N2) + offset2;

  // Optional subtle grid to enhance the vector/blueprint aesthetic
  const BackgroundGrid = () => (
    <svg width="100%" height="100%" style={{ position: "absolute", opacity: 0.05 }}>
      <defs>
        <pattern id="gridPattern" width="60" height="60" patternUnits="userSpaceOnUse">
          <path d="M 60 0 L 0 0 0 60" fill="none" stroke="#FFFFFF" strokeWidth="2" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#gridPattern)" />
    </svg>
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {!transparentBackground && <BackgroundGrid />}

      <svg width={width} height={height} style={{ overflow: "visible" }}>
        <defs>
          <filter id="gearShadow" x="-20%" y="-20%" width="140%" height="140%">
            <feDropShadow dx="0" dy="12" stdDeviation="15" floodOpacity="0.4" floodColor="#000000" />
          </filter>
        </defs>

        <g 
          filter={gearStyle === "Solid" ? "url(#gearShadow)" : undefined}
          transform={`translate(${centerX}, ${centerY}) scale(${zoomLevel}) translate(${-centerX}, ${-centerY})`}
        >
          {/* Primary Gear (Left) */}
          <Gear
            N={N1}
            Rp={Rp1}
            H={80} // Tooth Height
            Rhole={80} // Center hole radius
            color={primaryGearColor}
            rotation={angle1}
            x={x1}
            y={centerY}
            styleType={gearStyle}
            scale={entranceScale}
          />
          <circle
            cx={x1}
            cy={centerY}
            r={24 * entranceScale}
            fill={axleColor}
            style={{ transition: "none" }}
          />

          {/* Secondary Gear (Right) */}
          <Gear
            N={N2}
            Rp={Rp2}
            H={80}
            Rhole={50}
            color={secondaryGearColor}
            rotation={angle2}
            x={x2}
            y={centerY}
            styleType={gearStyle}
            scale={entranceScale}
          />
          <circle
            cx={x2}
            cy={centerY}
            r={24 * entranceScale}
            fill={axleColor}
            style={{ transition: "none" }}
          />
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default GearSync;